import torch, b200probe, statistics as st, time
COMMON = r'''
__device__ __forceinline__ float f(float g,float x,float s){return __fmul_rn(g,__fmul_rn(s,__fadd_rn(1.0f,__fmul_rn(x,__fsub_rn(1.0f,s)))));}
__device__ __forceinline__ float4 ld4(const float*p, unsigned long long pol){float4 v;
#if HINTS
 asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"l"(p),"l"(pol));
#else
 asm volatile("ld.global.v4.f32 {%0,%1,%2,%3}, [%4];":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"l"(p));
#endif
 return v;}
__device__ __forceinline__ void st4(float*p,float4 v,unsigned long long pol){
#if HINTS
 asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;"::"l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(pol):"memory");
#else
 asm volatile("st.global.v4.f32 [%0], {%1,%2,%3,%4};"::"l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w):"memory");
#endif
}
__device__ __forceinline__ float4 comp(float4 a,float4 b,float4 c){return make_float4(f(a.x,b.x,c.x),f(a.y,b.y,c.y),f(a.z,b.z,c.z),f(a.w,b.w,c.w));}
'''
R0 = r'''
extern "C" __global__ void __launch_bounds__(256) K(const float*__restrict__ g,const float*__restrict__ x,const float*__restrict__ s,float*__restrict__ o,long long n){
 const long long nvec=n>>2; const long long i=(long long)blockIdx.x*256+threadIdx.x;
 if(i<nvec){unsigned long long pl,ps;
  asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(pl));
  asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(ps));
  float4 a=ld4(g+(i<<2),pl),b=ld4(x+(i<<2),pl),c=ld4(s+(i<<2),pl); st4(o+(i<<2),comp(a,b,c),ps);
 } else if(i==nvec){for(long long e=nvec<<2;e<n;++e)o[e]=f(g[e],x[e],s[e]);}
}'''
def v1(cluster, hints, ept8=False):
    attr = '__cluster_dims__(2,1,1)' if cluster else ''
    pre = f'#define HINTS {1 if hints else 0}\n' + COMMON
    if not ept8:
        body = r'''
extern "C" __global__ ATTR void __launch_bounds__(256) K(const float*__restrict__ g,const float*__restrict__ x,const float*__restrict__ s,float*__restrict__ o,unsigned n){
 const unsigned nvec=n>>2; const unsigned i=blockIdx.x*256u+threadIdx.x;
 const unsigned long long pl=0x12F0000000000000ull, ps=0x14F0000000000000ull;
 if(i<nvec){
  float4 a=ld4(g+4*i,pl),b=ld4(x+4*i,pl),c=ld4(s+4*i,pl); st4(o+4*i,comp(a,b,c),ps);
 } else if(i==nvec){
  const unsigned e=nvec<<2; float ta[3],tb[3],tc[3];
  #pragma unroll
  for(int k=0;k<3;k++){ if(e+k<n){ta[k]=g[e+k];tb[k]=x[e+k];tc[k]=s[e+k];} }
  #pragma unroll
  for(int k=0;k<3;k++){ if(e+k<n) o[e+k]=f(ta[k],tb[k],tc[k]); }
 }
}'''
    else:
        body = r'''
extern "C" __global__ ATTR void __launch_bounds__(256) K(const float*__restrict__ g,const float*__restrict__ x,const float*__restrict__ s,float*__restrict__ o,unsigned n){
 const unsigned nvec=n>>2; const unsigned G=gridDim.x*256u; const unsigned i=blockIdx.x*256u+threadIdx.x; const unsigned j1=i+G;
 const unsigned long long pl=0x12F0000000000000ull, ps=0x14F0000000000000ull;
 float4 a0,b0,c0,a1,b1,c1;
 if(i<nvec){a0=ld4(g+4*i,pl);b0=ld4(x+4*i,pl);c0=ld4(s+4*i,pl);}
 if(j1<nvec){a1=ld4(g+4*j1,pl);b1=ld4(x+4*j1,pl);c1=ld4(s+4*j1,pl);}
 if(i<nvec) st4(o+4*i,comp(a0,b0,c0),ps);
 if(j1<nvec) st4(o+4*j1,comp(a1,b1,c1),ps);
 if(i==nvec||j1==nvec){
  const unsigned e=nvec<<2; float ta[3],tb[3],tc[3];
  #pragma unroll
  for(int k=0;k<3;k++){ if(e+k<n){ta[k]=g[e+k];tb[k]=x[e+k];tc[k]=s[e+k];} }
  #pragma unroll
  for(int k=0;k<3;k++){ if(e+k<n) o[e+k]=f(ta[k],tb[k],tc[k]); }
 }
}'''
    return pre + body.replace('ATTR', attr)
srcs = {'r0': (COMMON.replace('#if HINTS','#if 1')+R0) if False else ('#define HINTS 1\n'+COMMON+R0),
        'V1': v1(False,True), 'V2': v1(True,True), 'V3': v1(True,False), 'V4': v1(True,True,True)}
ks = {}
for k,v in srcs.items():
    try: ks[k]=b200probe.cuda_kernel(v,'K')
    except Exception as e: print(k,'COMPILE FAIL',str(e)[:800])
print(list(ks))
def launcher(name, n, g,x,s,o):
    k=ks[name]
    nvec=n>>2; thr=nvec+(1 if n&3 else 0)
    if name=='r0':
        grid=(thr+255)//256
        return lambda *a: k((grid,1,1),(256,1,1),g,x,s,o,n)
    if name=='V4':
        t=(thr+1)//2; grid=(t+255)//256
        if grid&1: grid+=1
        return lambda *a: k((grid,1,1),(256,1,1),g,x,s,o,n)
    grid=(thr+255)//256
    if name in('V2','V3') : grid+=grid&1
    return lambda *a: k((grid,1,1),(256,1,1),g,x,s,o,n)
n=4096
g,x,s=[torch.randn(n,device='cuda') for _ in range(3)]; o=torch.zeros(n,device='cuda')
ref=g*(s*(1+x*(1-s)))
for name in ks:
    o.zero_(); launcher(name,n,g,x,s,o)(); torch.cuda.synchronize()
    print(name,(o-ref).abs().max().item())

